/* CUSTOM */

/* 형광펜
   padding은 안쪽 여백, border-radius는 모서리 둥글기를 조절합니다. */
.mes_text q {
    quotes: none;
    color: var(--SmartThemeBodyColor);
    background-color: color-mix(in srgb, var(--SmartThemeBorderColor) 28%, transparent 72%);
    border: 0;
    margin: 0 0.06em;
    padding: 0.08em 0.30em;
    border-radius: 2px;
    font: inherit;
    box-decoration-break: clone;
    -webkit-box-decoration-break: clone;
}

/* 상단바 폰트 어썸
   content의 "\f..." 값은 폰트 어썸 유니코드입니다.
   유니코드 값을 변경하면 아이콘이 바뀌고,
   font-size 배수를 바꾸면 아이콘 크기가 달라집니다. */
#top-settings-holder .drawer-icon.closedIcon,
#top-settings-holder .drawer-icon.openIcon,
#top-bar .drawer-icon.closedIcon,
#top-bar .drawer-icon.openIcon {
    font-size: calc(var(--mainFontSize) * 1.46) !important;
}

/* 캐릭터 */
#rightNavDrawerIcon::before {
    content: "\f564";
}

/* 페르소나 */
#persona-management-button .drawer-icon::before {
    content: "\f0f4";
}

/* 배경 */
#backgrounds-button .drawer-icon::before {
    content: "\f03e";
}

/* 확장 */
#extensions-settings-button .drawer-icon::before {
    content: "\f187";
}

/* 로어 */
#WI-SP-button .drawer-icon::before {
    content: "\f02d";
}

/* 인풋창 폰트 어썸
   content의 "\f..." 값은 폰트 어썸 유니코드입니다.
   유니코드 값을 변경하면 아이콘이 바뀝니다. */

/* 전송 */
#send_but::before {
    content: "\f04b";
}

/* 정지 */
#send_form .mes_stop .fa-circle-stop::before {
    content: "\f04c";
}

/* 확장 메뉴 */
#extensionsMenuButton::before {
    content: "\f522";
}

/* THEME CSS */

:root {
    --iriver-surface: rgba(38, 31, 30, 1);
    --iriver-chrome-fill: color-mix(
        in srgb,
        var(--SmartThemeBlurTintColor) 92%,
        var(--SmartThemeBorderColor) 8%
    );
    --iriver-surface-soft: rgba(49, 38, 36, 1);
    --iriver-button-fill: color-mix(
        in srgb,
        var(--SmartThemeBorderColor) 22%,
        var(--SmartThemeBlurTintColor) 78%
    );
    --iriver-line-soft: color-mix(
        in srgb,
        var(--SmartThemeBorderColor) 62%,
        transparent 38%
    );
    --iriver-muted: var(--SmartThemeUnderlineColor);
    --iriver-slider-track: var(--iriver-line-soft);
    --iriver-slider-thumb: var(--SmartThemeUnderlineColor);
    --iriver-accent-overlay: color-mix(
        in srgb,
        var(--SmartThemeBorderColor) 7%,
        transparent 93%
    );
    --iriver-info-fill: color-mix(
        in srgb,
        var(--SmartThemeBorderColor) 8%,
        var(--SmartThemeBotMesBlurTintColor) 92%
    );
    --iriver-quote-fill: color-mix(
        in srgb,
        var(--SmartThemeBorderColor) 5%,
        transparent 95%
    );
    --iriver-inline-code-fill: color-mix(
        in srgb,
        var(--SmartThemeBorderColor) 10%,
        transparent 90%
    );
    --topBarBlockSize: calc(var(--mainFontSize) * 2.63);
    --iriver-scroll-gauge: 3px;
    --iriver-chat-inset: calc(9px + var(--iriver-scroll-gauge));
    --iriver-send-control-size: var(--bottomFormBlockSize, 34px);
}

/* Base typography: follow SillyTavern's selected font in native controls. */
code,
textarea,
#send_textarea,
input,
select,
button,
.text_pole,
.font-family-reset {
    font-family: inherit;
}

.drawer-icon,
.drawer.openDrawer,
.drawer.openDrawer > .drawer-icon,
.drawer.openDrawer > .drawer-toggle {
    background: transparent !important;
    background-image: none !important;
    border-color: transparent !important;
    box-shadow: none !important;
    outline: 0 !important;
}

.drawer-icon.closedIcon {
    opacity: 0.70;
}

.drawer-icon.closedIcon::before {
    color: var(--SmartThemeUnderlineColor);
}

.drawer-icon.openIcon,
.drawer.openDrawer > .drawer-icon {
    color: var(--SmartThemeBodyColor);
    opacity: 1;
}

/* Keep the top bar and opened settings drawer on the same boundary. */
#top-bar {
    height: var(--topBarBlockSize);
    box-sizing: border-box !important;
    background-color: color-mix(
        in srgb,
        var(--iriver-chrome-fill) 50%,
        transparent 50%
    ) !important;
    border: 1px solid var(--SmartThemeBorderColor) !important;
    border-radius: 6px 6px 0 0 !important;
    box-shadow: none;
}

/* Keep the side rails attached to the chat area itself.
   They now stop exactly where the input form begins at every size. */
#sheld::before,
#sheld::after {
    content: none !important;
    display: none !important;
}

#chat {
    padding-block: var(--iriver-chat-inset);
    padding-inline-start: var(--iriver-chat-inset);
    padding-inline-end: 9px;
    overflow-y: scroll;
    border-inline: 1px solid var(--SmartThemeBorderColor);
    border-block: 0;
}

body.no-blur #top-bar {
    background-color: var(--iriver-chrome-fill) !important;
}

#clickSlidersTips,
#left-nav-panel > a.topRightInset {
    display: none !important;
}

/* Theme color zones using the active iRiver palette.
   The outer .popup shell stays transparent; its actual modal content
   keeps the theme background through .popup .popper-modal. */
.drawer-content,
#right-nav-panel,
#left-nav-panel,
.ui-widget.ui-widget-content,
#bulk_tag_popup,
#dialogue_popup,
#options,
#extensionsMenu,
.popup .popper-modal,
.select2-dropdown,
#select_chat_popup,
#floatingPrompt,
#cfgConfig,
#logprobsViewer,
#movingDivs > div,
.extensions_toolbar {
    background-color: var(--SmartThemeBlurTintColor) !important;
}

.select2-dropdown {
    box-shadow: none !important;
    text-shadow: none !important;
    filter: none !important;
}

#rm_extensions_block .extensions_block
> hr:has(+ .flex-container #extensions_status),
#rm_extensions_block .extensions_block
> .flex-container:has(#extensions_status),
#rm_extensions_block .extensions_block
> .flex-container:has(#extensions_url) {
    display: none !important;
}

#extensionsMenu {
    max-height: 35vh;
    max-height: 35dvh;
    overflow-y: auto;
    overflow-x: hidden;
    overscroll-behavior: contain;
}

.openai-tab-buttons {
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
    box-shadow: none;
}

.openai-tab-button.active {
    box-shadow: none;
}

#extensionTopBarChatName {
    align-self: center !important;
    position: relative !important;
    inset-block-start: 2px !important;
    background: transparent !important;
    border: 0 !important;
    box-shadow: none !important;
}

@media (hover: hover) and (pointer: fine) {
  #extensionTopBar {
    border-radius: 0 !important;
    border-top: 0 !important;
  }
}

.popup:has(#rawPromptPopup) .popup-content {
    min-height: 0;
    overflow-y: auto;
}

/* Apple WebKit layout corrections, expressed with logical dimensions. */
@supports (-webkit-touch-callout: none) {
    #chat {
        padding-inline-end: var(--iriver-chat-inset);
    }

    :is(.drawer-content):not(#left-nav-panel):not(#right-nav-panel) {
        max-inline-size: 100dvw;
    }

    #world_popup {
        inline-size: 100%;
        max-inline-size: 100dvw;
        overflow-x: hidden;
    }

    #WorldInfo {
        inline-size: 100%;
        max-inline-size: 100%;
        min-inline-size: 0;
        overflow-x: hidden;
    }

    #WorldInfo .wi-card-entry {
        max-inline-size: 100%;
        min-inline-size: 0;
        box-sizing: border-box;
    }

    @media screen and (min-width: 768px) {
        #sheld {
            inline-size: var(--sheldWidth);
            margin-inline: auto;
        }

        #top-settings-holder .drawer .drawer-content {
            inline-size: var(--sheldWidth);
        }

        :is(
            #left-nav-panel,
            #right-nav-panel,
            #character_popup,
            #world_popup,
            .drawer-content
        ) {
            inset-block-start: var(--topBarBlockSize);
        }

        :is(#character_popup, #world_popup, .drawer-content) {
            margin-block-start: 0;
        }
    }

    /* Preserve desktop top-bar width; tablet Safari uses SillyTavern's full-width bar. */
    @media screen and (min-width: 1001px) {
        #top-bar {
            inline-size: var(--sheldWidth);
        }
    }
}

.menu_button,
.popup-button,
.selectable_button,
input[type="button"],
input[type="submit"],
.paginationjs-pages li > a,
.paginationjs-pages li > span {
    color: var(--SmartThemeBodyColor);
    background-color: var(--iriver-button-fill) !important;
    border: 0 !important;
    box-shadow: none !important;
    text-shadow: none !important;
    filter: none !important;
}

.menu_button.toggleable {
    position: relative;
}

#top-bar .menu_button,
.inline-drawer-icon,
.mes_button,
.mes_edit_buttons .menu_button,
.mes_reasoning_actions .edit_button,
#leftSendForm > div,
#rightSendForm > div,
#send_but,
#send_form .mes_stop {
    background: transparent !important;
    border-color: transparent !important;
    box-shadow: none !important;
}

/* iRiver reasoning / thinking block */
.mes_reasoning_details {
    margin: 8px 18px 10px !important;
    color: var(--SmartThemeBodyColor) !important;
}

/* Keep the thinking title and its action buttons together, inside the message. */
.mes_reasoning_details .mes_reasoning_summary {
    width: 100% !important;
    min-width: 0 !important;
    margin-right: 0 !important;
    padding-right: 2px !important;
    box-sizing: border-box;
    align-items: center !important;
    justify-content: flex-start !important;
    column-gap: 8px !important;
    overflow: visible !important;
}

.mes_reasoning_header_block {
    flex: 0 1 auto !important;
    flex-grow: 0 !important;
    min-width: 0;
    max-width: calc(100% - 98px) !important;
    background: transparent !important;
    background-image: none !important;
    border: 0 !important;
    box-shadow: none !important;
    filter: none !important;
}

.mes_reasoning_header {
    width: clamp(220px, 32vw, 320px) !important;
    min-width: 0;
    max-width: 100% !important;
    box-sizing: border-box;
    margin: 0.5em 2px !important;
    padding: 8px 12px !important;
    color: var(--SmartThemeBodyColor) !important;
    background: var(--iriver-surface-soft) !important;
    background-color: var(--iriver-surface-soft) !important;
    background-image: none !important;
    border: 1px solid var(--iriver-line-soft) !important;
    border-radius: 6px !important;
    box-shadow: none !important;
    filter: none !important;
    text-shadow: none !important;
}

.mes_reasoning_header_title {
    flex: 1 1 auto !important;
    min-width: 0;
    color: var(--SmartThemeBodyColor) !important;
    font-weight: 500 !important;
    opacity: 0.90 !important;
    white-space: nowrap !important;
    overflow: hidden !important;
    text-overflow: ellipsis !important;
}

.mes_reasoning_arrow {
    flex: 0 0 auto !important;
}

.mes_reasoning_actions {
    flex: 0 0 auto !important;
    min-width: 0 !important;
    margin: 0 !important;
    padding: 0 2px 0 0 !important;
    align-items: center !important;
    column-gap: 2px !important;
    overflow: visible !important;
}

.mes_reasoning_actions .mes_button,
.mes_reasoning_actions .menu_button {
    flex: 0 0 28px !important;
    width: 28px !important;
    min-width: 28px !important;
    height: 28px !important;
    padding: 0 !important;
    margin: 0 !important;
    align-items: center !important;
    justify-content: center !important;
}

.mes_reasoning_arrow,
.mes_reasoning_header .fa-solid,
.mes_reasoning_header .fa-regular,
.mes_reasoning_actions,
.mes_reasoning_actions .menu_button,
.mes_reasoning_actions .mes_button,
.mes_reasoning_actions .edit_button {
    color: var(--iriver-muted) !important;
    background: transparent !important;
    background-color: transparent !important;
    background-image: none !important;
    border: 0 !important;
    box-shadow: none !important;
    filter: none !important;
    text-shadow: none !important;
    opacity: 0.88 !important;
}

.mes_reasoning {
    min-width: 0;
    margin: 6px 0 0 !important;
    padding: 12px 14px !important;
    box-sizing: border-box;
    color: var(--SmartThemeBodyColor) !important;
    background: var(--iriver-surface) !important;
    background-color: var(--iriver-surface) !important;
    background-image: none !important;
    border: 1px solid var(--iriver-line-soft) !important;
    border-radius: 6px !important;
    box-shadow: none !important;
    filter: none !important;
    text-shadow: none !important;
    line-height: 1.62;
    overflow-wrap: anywhere;
}

.mes_reasoning > :first-child {
    margin-top: 0 !important;
}

.mes_reasoning > :last-child {
    margin-bottom: 0 !important;
}

select,
.text_pole {
    color: var(--SmartThemeBodyColor) !important;
    background-color: var(--iriver-surface) !important;
    border: 1px solid var(--SmartThemeBorderColor) !important;
    box-shadow: none !important;
    filter: none !important;
}

textarea:not(.text_pole):not(.select2-search__field),
.neo-range-input,
.range-block-counter input,
input[type="number"],
input[type="search"],
input[type="password"],
input[type="url"],
input[type="email"],
.select2-container .select2-selection--single,
.select2-container .select2-selection--multiple,
.select2-container .select2-selection__choice {
    color: var(--SmartThemeBodyColor) !important;
    background-color: var(--iriver-surface) !important;
    background-image: none !important;
    border: 1px solid var(--SmartThemeBorderColor) !important;
    box-shadow: none !important;
    filter: none !important;
}

select option {
    color: var(--SmartThemeBodyColor) !important;
    background-color: var(--iriver-surface) !important;
}

/* Keep selected items visible in native mobile multi-select controls. */
select[multiple] option:checked {
    color: var(--SmartThemeBodyColor) !important;
    background-color: var(--iriver-button-fill) !important;
}


/* Keep active flat menu buttons visibly distinct. */
.menu_button:not(.disabled):not([disabled]).active {
    color: var(--SmartThemeUnderlineColor) !important;
}

select option[disabled]:not(:checked) {
    color: var(--iriver-muted) !important;
    opacity: 0.65;
}

/* Unified SillyTavern sliders */
.neo-range-slider,
input[type="range"] {
    -webkit-appearance: none !important;
    appearance: none !important;
    height: 3px !important;
    accent-color: var(--iriver-slider-thumb) !important;
    background: var(--iriver-slider-track) !important;
    background-image: none !important;
    border: 0 !important;
    border-radius: 999px !important;
    box-shadow: none !important;
    filter: none !important;
}

.neo-range-slider:hover,
input[type="range"]:hover {
    filter: none !important;
}

.neo-range-slider:focus-visible,
input[type="range"]:focus-visible {
    outline: 1px solid var(--iriver-slider-thumb) !important;
    outline-offset: 3px !important;
}

.neo-range-slider:disabled,
input[type="range"]:disabled {
    cursor: not-allowed !important;
    opacity: 0.45 !important;
}

.neo-range-slider::-webkit-slider-runnable-track,
input[type="range"]::-webkit-slider-runnable-track {
    height: 3px !important;
    background: transparent !important;
    border: 0 !important;
    border-radius: 999px !important;
    box-shadow: none !important;
}

.neo-range-slider::-webkit-slider-thumb,
input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none !important;
    appearance: none !important;
    width: 12px !important;
    height: 12px !important;
    margin-top: -4.5px !important;
    background: var(--iriver-slider-thumb) !important;
    border: 1px solid var(--SmartThemeBorderColor) !important;
    border-radius: 50% !important;
    box-shadow: none !important;
    filter: none !important;
}

.neo-range-slider::-moz-range-track,
input[type="range"]::-moz-range-track {
    height: 3px !important;
    background: var(--iriver-slider-track) !important;
    border: 0 !important;
    border-radius: 999px !important;
    box-shadow: none !important;
}

.neo-range-slider::-moz-range-progress,
input[type="range"]::-moz-range-progress {
    height: 3px !important;
    background: var(--iriver-slider-thumb) !important;
    border: 0 !important;
    border-radius: 999px !important;
    box-shadow: none !important;
}

.neo-range-slider::-moz-range-thumb,
input[type="range"]::-moz-range-thumb {
    width: 12px !important;
    height: 12px !important;
    background: var(--iriver-slider-thumb) !important;
    border: 1px solid var(--SmartThemeBorderColor) !important;
    border-radius: 50% !important;
    box-shadow: none !important;
    filter: none !important;
}

.doubleRangeContainer > .doubleRangeInputContainer::after {
    height: 3px !important;
    background-color: var(--iriver-slider-thumb) !important;
    box-shadow: none !important;
}

/* Theme checkboxes */
input[type="checkbox"] {
    background-color: var(--iriver-surface) !important;
    border: 1px solid var(--SmartThemeBorderColor) !important;
    outline: 0 !important;
    box-shadow: none !important;
    filter: none !important;
}

input[type="checkbox"]::before {
    box-shadow: inset 1em 1em var(--SmartThemeUnderlineColor) !important;
}

input[type="checkbox"]:disabled {
    background-color: color-mix(
        in srgb,
        var(--iriver-surface) 82%,
        var(--SmartThemeBorderColor) 18%
    ) !important;
    opacity: 0.65;
}

#completion_prompt_manager .completion_prompt_manager_header_advanced,
#completion_prompt_manager .completion_prompt_manager_header_advanced > *,
#completion_prompt_manager .completion_prompt_manager_header_advanced .menu_button,
#completion_prompt_manager .completion_prompt_manager_header_advanced [aria-selected="true"],
#completion_prompt_manager .completion_prompt_manager_header_advanced .active,
#completion_prompt_manager .completion_prompt_manager_header_advanced .selected {
    color: var(--SmartThemeBodyColor) !important;
    background: var(--iriver-surface-soft) !important;
    background-image: none !important;
    box-shadow: none !important;
    text-shadow: none !important;
    filter: none !important;
}

#WorldInfo .select2-selection--single,
#WorldInfo .select2-selection--multiple,
#WorldInfo .select2-selection__choice,
#WorldInfo .text_pole,
#WorldInfo select {
    background-color: var(--iriver-surface) !important;
    box-shadow: none !important;
}

#WorldInfo .select2-selection--single,
#WorldInfo .select2-selection--multiple,
#WorldInfo .select2-selection__choice {
    border-radius: 0 !important;
}

#WorldInfo #WIMultiSelector .select2-selection--multiple,
#WorldInfo #WIMultiSelector
.select2-container--focus .select2-selection--multiple {
    border: 1px solid var(--iriver-line-soft) !important;
    outline: 0 !important;
    box-shadow: none !important;
}

.wi-card-entry {
    border-radius: 0 !important;
}

/* Lorebook activation settings use the active light theme palette. */
#WorldInfo #wiActivationSettings,
#WorldInfo .standoutHeader ~ .inline-drawer-content {
    background-color: var(--SmartThemeBlurTintColor) !important;
}

#WorldInfo #world_info_sort_order,
#WorldInfo #world_backfill_memos {
    display: none;
}

#WorldInfo #wiTopBlock {
    display: flex;
    flex-direction: column;
    align-items: stretch;
    gap: 0;
    height: auto;
    min-height: 0;
    margin: 0;
    padding: 0;
}

#WorldInfo #wiTopBlock > .range-block {
    flex: 0 0 auto;
    box-sizing: border-box;
    width: 100%;
    height: auto;
    min-height: 0;
    margin: 0;
    padding: 0;
}

#WorldInfo .range-block-title:has(
    [data-i18n="Active World(s) for all chats"]
),
#WorldInfo .range-block-title:has(
    [data-i18n="Global World Info/Lorebook activation settings"]
) {
    display: none;
}

#WorldInfo #WIMultiSelector .range-block-range,
#WorldInfo #WIMultiSelector .select2-container,
#WorldInfo #WIMultiSelector .selection {
    box-sizing: border-box !important;
    width: 100% !important;
    min-height: 24px !important;
    margin: 0 !important;
    padding: 0 !important;
}

#WorldInfo #WIMultiSelector .select2-selection--multiple {
    position: relative !important;
    display: flex !important;
    align-items: center !important;
    box-sizing: border-box !important;
    width: 100% !important;
    height: auto !important;
    min-height: 24px !important;
    margin: 0 !important;
    padding: 1px 24px 1px 4px !important;
    overflow: visible !important;
}

#WorldInfo #WIMultiSelector .select2-selection__rendered {
    display: flex !important;
    align-items: center !important;
    flex-wrap: wrap !important;
    gap: 2px !important;
    box-sizing: border-box !important;
    width: 100% !important;
    min-height: 20px !important;
    margin: 0 !important;
    padding: 0 !important;
    list-style: none !important;
    overflow: visible !important;
}

#WorldInfo #WIMultiSelector
.select2-selection--multiple:not(:has(.select2-selection__choice)) {
    height: 24px !important;
    max-height: 24px !important;
    padding: 0 !important;
}

#WorldInfo #WIMultiSelector
.select2-selection--multiple:not(:has(.select2-selection__choice))
.select2-selection__rendered {
    height: 100% !important;
    min-height: 0 !important;
}

#WorldInfo #WIMultiSelector
.select2-selection--multiple:not(:has(.select2-selection__choice))
.select2-search--inline {
    position: absolute !important;
    z-index: 4 !important;
    inset: 0 !important;
    display: block !important;
    float: none !important;
    box-sizing: border-box !important;
    width: 100% !important;
    height: 100% !important;
    margin: 0 !important;
    padding: 0 !important;
}

#WorldInfo #WIMultiSelector .select2-search__field,
#WorldInfo #WIMultiSelector .select2-search__field:focus {
    display: block !important;
    box-sizing: border-box !important;
    width: 100% !important;
    height: 100% !important;
    min-height: 0 !important;
    max-height: 100% !important;
    margin: 0 !important;
    padding: 0 10px !important;
    color: var(--SmartThemeBodyColor) !important;
    font-size: calc(var(--mainFontSize) * 0.9) !important;
    text-align: start !important;
    text-indent: 0 !important;
    direction: ltr !important;
    line-height: 22px !important;
    border: 0 !important;
    outline: 0 !important;
    box-shadow: none !important;
