#character_sort_order .fa-solid,
#character_sort_order .fa-regular {
    font-size: calc(var(--mainFontSize) * 0.78) !important;
}

.avatar-container.selected {
    border-color: var(--SmartThemeBorderColor) !important;
    box-shadow: none !important;
}

.avatar-container.selected .avatar,
.avatar-container.default_persona .avatar {
    outline-color: var(--SmartThemeUnderlineColor) !important;
}

#HotSwapWrapper {
    overflow-x: hidden;
    overflow-y: hidden;
}

#HotSwapWrapper > div {
    overflow-x: auto;
    overflow-y: hidden;
    flex-flow: row nowrap;
    justify-content: flex-start;
    column-gap: 8px;
    row-gap: 0;
}

#rm_button_characters {
    width: auto !important;
    min-width: 0 !important;
    font-size: calc(var(--mainFontSize) * 1.12) !important;
    line-height: 1 !important;
    transform: none !important;
}

#rm_button_characters .fa-list-ul,
#rm_button_characters .fa-list,
#rm_button_characters .fa-solid,
#rm_button_characters .fa-regular {
    font-size: inherit !important;
    line-height: inherit !important;
}

/* Character tags use the active iRiver palette instead of stored tag colors. */
#right-nav-panel #tagList .tag,
#right-nav-panel .character_select .tags_inline .tag,
#right-nav-panel .group_select .tags_inline .tag {
    color: var(--SmartThemeBodyColor) !important;
    background-color: var(--iriver-button-fill) !important;
    border-color: var(--iriver-line-soft) !important;
    box-shadow: none !important;
    filter: none !important;
    text-shadow: none !important;
    opacity: 1 !important;
}

#right-nav-panel .character_select .tags_inline,
#right-nav-panel .group_select .tags_inline {
    opacity: 1;
}

#right-nav-panel #tagList .tag_remove {
    color: var(--iriver-muted) !important;
}


/* Firefox scrollbar fallback */
@supports (-moz-appearance: none) {
    * {
        scrollbar-width: thin;
        scrollbar-color: var(--SmartThemeUnderlineColor) transparent;
    }
}

/* Global themed scrollbars */
::-webkit-scrollbar {
    width: var(--iriver-scroll-gauge);
    height: var(--iriver-scroll-gauge);
}

::-webkit-scrollbar-track {
    background: transparent;
    border-radius: 999px !important;
}

::-webkit-scrollbar-thumb,
::-webkit-scrollbar-thumb:vertical,
::-webkit-scrollbar-thumb:horizontal {
    background-color: var(--SmartThemeUnderlineColor);
    border: 0;
    border-radius: 999px !important;
    box-shadow: none;
}

::-webkit-scrollbar-corner {
    background: transparent;
}

#options .options-content {
    border: 0 !important;
    border-radius: 0 !important;
}
